#!/usr/bin/env sh
# fetch TAGO bus arrival prediction (MOLIT, data.go.kr) (KR) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="http://apis.data.go.kr/1613000/ArvlInfoInqireService/getSttnAcctoArvlPrearngeInfoList?serviceKey=DUMMY&cityCode=23&nodeId=ICB165000487&numOfRows=1&_type=json"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
